/**
 * Low-Level Design: Tic Tac Toe
 * Design Patterns Applied:
 *  - Strategy Pattern: Pluggable AI / bot move strategies
 *  - Singleton Pattern: Match coordinator instance
 *  - Observer Pattern: Real-time board state change listener
 */

#include <iostream>
#include <vector>
#include <queue>
#include <string>
#include <memory>
#include <cmath>

enum class Symbol { EMPTY, X, O };

// --- [DESIGN PATTERN: Observer] Observer pattern for board changes ---
class BoardObserver {
public:
    virtual ~BoardObserver() = default;
    virtual void onMove(int r, int c, Symbol s) = 0;
};

class ConsoleObserver : public BoardObserver {
public:
    void onMove(int r, int c, Symbol s) override {
        std::cout << ">> [Observer] Move played at (" << r << ", " << c << ")\n";
    }
};

class Cell {
    int r, c;
    Symbol symbol;
public:
    Cell(int r = 0, int c = 0) : r(r), c(c), symbol(Symbol::EMPTY) {}
    bool isEmpty() const { return symbol == Symbol::EMPTY; }
    Symbol getSymbol() const { return symbol; }
    void setSymbol(Symbol s) { symbol = s; }
};

class Board {
    int size;
    std::vector<std::vector<Cell>> grid;
    std::vector<std::shared_ptr<BoardObserver>> observers;
public:
    Board(int s) : size(s), grid(s, std::vector<Cell>(s)) {
        for (int i = 0; i < s; i++)
            for (int j = 0; j < s; j++)
                grid[i][j] = Cell(i, j);
    }
    void addObserver(std::shared_ptr<BoardObserver> obs) { observers.push_back(obs); }
    bool place(int r, int c, Symbol s) {
        if (r < 0 || r >= size || c < 0 || c >= size || !grid[r][c].isEmpty()) return false;
        grid[r][c].setSymbol(s);
        for (auto& obs : observers) obs->onMove(r, c, s);
        return true;
    }
    void print() const {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                char ch = grid[i][j].getSymbol() == Symbol::EMPTY ? '.' :
                          (grid[i][j].getSymbol() == Symbol::X ? 'X' : 'O');
                std::cout << ch << " ";
            }
            std::cout << "\n";
        }
        std::cout << "---\n";
    }
    int getSize() const { return size; }
};

// --- [DESIGN PATTERN: Strategy] Move decision strategy ---
class MoveStrategy {
public:
    virtual ~MoveStrategy() = default;
    virtual std::pair<int, int> pickMove(const Board& board) = 0;
};

struct Player {
    std::string name;
    Symbol symbol;
};

// --- [DESIGN PATTERN: Singleton / Coordinator] Match coordinator ---
class TicTacToeGame {
    Board board;
    std::queue<Player> players;
    std::vector<int> rows, cols;
    int diag = 0, antiDiag = 0, moves = 0;
    bool gameOver = false;
public:
    TicTacToeGame(int s, Player p1, Player p2) : board(s), rows(s, 0), cols(s, 0) {
        board.addObserver(std::make_shared<ConsoleObserver>());
        players.push(p1);
        players.push(p2);
    }

    bool makeMove(int r, int c) {
        if (gameOver) return false;
        Player curr = players.front();
        if (!board.place(r, c, curr.symbol)) return false;

        moves++;
        int val = (curr.symbol == Symbol::X) ? 1 : -1;
        rows[r] += val;
        cols[c] += val;
        if (r == c) diag += val;
        if (r + c == board.getSize() - 1) antiDiag += val;

        board.print();

        int target = board.getSize();
        if (std::abs(rows[r]) == target || std::abs(cols[c]) == target ||
            std::abs(diag) == target || std::abs(antiDiag) == target) {
            std::cout << "🎉 Player " << curr.name << " WINS!\n";
            gameOver = true;
            return true;
        }
        if (moves == target * target) {
            std::cout << "🤝 Draw game!\n";
            gameOver = true;
            return true;
        }

        players.pop();
        players.push(curr);
        return true;
    }
};

int main() {
    Player p1{"Alice", Symbol::X};
    Player p2{"Bob", Symbol::O};
    TicTacToeGame game(3, p1, p2);
    game.makeMove(0, 0);
    game.makeMove(0, 1);
    game.makeMove(1, 1);
    game.makeMove(0, 2);
    game.makeMove(2, 2);
    return 0;
}

