"""
Low-Level Design: Tic Tac Toe
Design Patterns Applied:
 - Strategy Pattern: Pluggable AI / bot move strategies and O(1) win verification
 - Singleton Pattern: Central game coordinator orchestrator
 - Observer Pattern: Real-time board state change subscriber notification
"""

from collections import deque
from enum import Enum
from abc import ABC, abstractmethod
from typing import List, Tuple

class Symbol(Enum):
    EMPTY = "."
    X = "X"
    O = "O"

# --- [DESIGN PATTERN: Observer] Subscriber for board move events ---
class BoardObserver(ABC):
    @abstractmethod
    def on_move_made(self, r: int, c: int, symbol: Symbol) -> None:
        pass

class ConsoleLoggerObserver(BoardObserver):
    def on_move_made(self, r: int, c: int, symbol: Symbol) -> None:
        print(f">> [Observer] Move played: ({r}, {c}) by {symbol.value}")

# --- [DESIGN PATTERN: Strategy] Pluggable bot move strategy ---
class MoveStrategy(ABC):
    @abstractmethod
    def determine_move(self, board_size: int, grid: List[List[Symbol]]) -> Tuple[int, int]:
        pass

class FirstAvailableMoveStrategy(MoveStrategy):
    def determine_move(self, board_size: int, grid: List[List[Symbol]]) -> Tuple[int, int]:
        for r in range(board_size):
            for c in range(board_size):
                if grid[r][c] == Symbol.EMPTY:
                    return (r, c)
        return (-1, -1)

class Board:
    def __init__(self, size: int):
        self.size = size
        self.grid = [[Symbol.EMPTY for _ in range(size)] for _ in range(size)]
        self.observers: List[BoardObserver] = []

    def add_observer(self, obs: BoardObserver) -> None:
        self.observers.append(obs)

    def place(self, r: int, c: int, symbol: Symbol) -> bool:
        if not (0 <= r < self.size and 0 <= c < self.size) or self.grid[r][c] != Symbol.EMPTY:
            return False
        self.grid[r][c] = symbol
        for obs in self.observers:
            obs.on_move_made(r, c, symbol)
        return True

    def display(self) -> None:
        for row in self.grid:
            print(" ".join(c.value for c in row))
        print("---")

# --- [DESIGN PATTERN: Singleton / Context] Game manager controlling state loop ---
class TicTacToeGame:
    def __init__(self, size: int, p1_name: str, p2_name: str):
        self.board = Board(size)
        self.board.add_observer(ConsoleLoggerObserver())
        self.players = deque([
            {"name": p1_name, "symbol": Symbol.X, "strategy": FirstAvailableMoveStrategy()},
            {"name": p2_name, "symbol": Symbol.O, "strategy": FirstAvailableMoveStrategy()}
        ])
        self.rows = [0] * size
        self.cols = [0] * size
        self.diag = 0
        self.anti_diag = 0
        self.moves = 0
        self.game_over = False

    def make_move(self, r: int, c: int) -> bool:
        if self.game_over:
            return False
        curr = self.players[0]
        if not self.board.place(r, c, curr["symbol"]):
            return False

        self.moves += 1
        val = 1 if curr["symbol"] == Symbol.X else -1
        self.rows[r] += val
        self.cols[c] += val
        if r == c:
            self.diag += val
        if r + c == self.board.size - 1:
            self.anti_diag += val

        self.board.display()

        target = self.board.size
        if any(abs(x) == target for x in [self.rows[r], self.cols[c], self.diag, self.anti_diag]):
            print(f"🎉 {curr['name']} ({curr['symbol'].value}) WINS!")
            self.game_over = True
            return True

        if self.moves == target * target:
            print("🤝 DRAW Game!")
            self.game_over = True
            return True

        self.players.rotate(-1)
        return True

if __name__ == "__main__":
    game = TicTacToeGame(3, "Alice", "Bob")
    moves = [(0, 0), (0, 1), (1, 1), (0, 2), (2, 2)]
    for r, c in moves:
        game.make_move(r, c)

