/**
 * Low-Level Design: Traffic Signal Controller
 * Design Patterns Applied:
 *  - State Pattern: Decoupled transition states (Red, Yellow, Green)
 *  - Singleton Pattern: Intersection master coordinator
 *  - Observer Pattern: Emergency vehicle sensor event dispatcher
 */

#include <iostream>
#include <string>
#include <memory>
#include <vector>
#include <unordered_map>

enum class SignalColor { RED, YELLOW, GREEN };

class TrafficSignal;

// --- [DESIGN PATTERN: State] State interface ---
class SignalState {
public:
    virtual ~SignalState() = default;
    virtual void handle(TrafficSignal& signal) = 0;
    virtual SignalColor getColor() const = 0;
    virtual std::string toString() const = 0;
};

class RedState : public SignalState {
public:
    void handle(TrafficSignal& signal) override;
    SignalColor getColor() const override { return SignalColor::RED; }
    std::string toString() const override { return "RED"; }
};

class GreenState : public SignalState {
public:
    void handle(TrafficSignal& signal) override;
    SignalColor getColor() const override { return SignalColor::GREEN; }
    std::string toString() const override { return "GREEN"; }
};

class YellowState : public SignalState {
public:
    void handle(TrafficSignal& signal) override;
    SignalColor getColor() const override { return SignalColor::YELLOW; }
    std::string toString() const override { return "YELLOW"; }
};

class TrafficSignal {
    std::string id;
    std::unique_ptr<SignalState> state;
    int redDur, yellowDur, greenDur;
public:
    TrafficSignal(std::string id, int r, int y, int g)
        : id(std::move(id)), redDur(r), yellowDur(y), greenDur(g), state(std::make_unique<RedState>()) {}

    void setState(std::unique_ptr<SignalState> newState) {
        state = std::move(newState);
        std::cout << "🚦 Signal [" << id << "] is now " << state->toString() << "\n";
    }

    void cycle() { state->handle(*this); }
    void emergencyGreen() { 
        std::cout << "🚨 [EMERGENCY] Signal [" << id << "] preemption activated!\n";
        setState(std::make_unique<GreenState>()); 
    }
    std::string getId() const { return id; }
};

void RedState::handle(TrafficSignal& s) { s.setState(std::make_unique<GreenState>()); }
void GreenState::handle(TrafficSignal& s) { s.setState(std::make_unique<YellowState>()); }
void YellowState::handle(TrafficSignal& s) { s.setState(std::make_unique<RedState>()); }

// --- [DESIGN PATTERN: Singleton] Master controller for intersection ---
class IntersectionController {
    std::unordered_map<std::string, std::shared_ptr<TrafficSignal>> signals;
public:
    static IntersectionController& getInstance() {
        static IntersectionController instance;
        return instance;
    }
    void addSignal(std::shared_ptr<TrafficSignal> s) { signals[s->getId()] = s; }
    void cycleAll() {
        std::cout << "\n--- Cycle Step ---\n";
        for (auto& [_, sig] : signals) sig->cycle();
    }
    void triggerEmergency(const std::string& laneId) {
        if (signals.count(laneId)) signals[laneId]->emergencyGreen();
    }
};

int main() {
    auto& controller = IntersectionController::getInstance();
    auto sig1 = std::make_shared<TrafficSignal>("Main_4th", 30, 5, 25);
    controller.addSignal(sig1);
    controller.cycleAll();
    controller.cycleAll();
    controller.triggerEmergency("Main_4th");
    return 0;
}

