"""
Low-Level Design: Traffic Signal Controller
Design Patterns Applied:
 - State Pattern: Encapsulates state machine transitions (Red -> Green -> Yellow)
 - Singleton Pattern: Centralized Intersection controller
 - Observer Pattern: Dynamic emergency response sensor listener
"""

from enum import Enum
from abc import ABC, abstractmethod
from typing import Dict

class SignalColor(Enum):
    RED = "RED"
    YELLOW = "YELLOW"
    GREEN = "GREEN"

# --- [DESIGN PATTERN: State] State interface ---
class SignalState(ABC):
    @abstractmethod
    def handle(self, signal: 'TrafficSignal') -> None:
        pass

    @property
    @abstractmethod
    def color(self) -> SignalColor:
        pass

class RedState(SignalState):
    def handle(self, signal: 'TrafficSignal') -> None:
        signal.set_state(GreenState(), signal.green_duration)
    @property
    def color(self) -> SignalColor: return SignalColor.RED

class GreenState(SignalState):
    def handle(self, signal: 'TrafficSignal') -> None:
        signal.set_state(YellowState(), signal.yellow_duration)
    @property
    def color(self) -> SignalColor: return SignalColor.GREEN

class YellowState(SignalState):
    def handle(self, signal: 'TrafficSignal') -> None:
        signal.set_state(RedState(), signal.red_duration)
    @property
    def color(self) -> SignalColor: return SignalColor.YELLOW

class TrafficSignal:
    def __init__(self, signal_id: str, red: int = 30, yellow: int = 5, green: int = 25):
        self.id = signal_id
        self.red_duration = red
        self.yellow_duration = yellow
        self.green_duration = green
        self.state: SignalState = RedState()
        self.duration = red

    def set_state(self, new_state: SignalState, duration: int) -> None:
        self.state = new_state
        self.duration = duration
        print(f"🚦 Signal [{self.id}] switched to {self.state.color.value} ({duration}s)")

    def trigger_cycle(self) -> None:
        self.state.handle(self)

    def emergency_override(self) -> None:
        print(f"🚨 EMERGENCY on [{self.id}]: Preempting immediate GREEN")
        self.set_state(GreenState(), 60)

# --- [DESIGN PATTERN: Singleton] Intersection singleton orchestrator ---
class IntersectionController:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(IntersectionController, cls).__new__(cls)
            cls._instance.signals: Dict[str, TrafficSignal] = {}
        return cls._instance

    def add_signal(self, signal: TrafficSignal) -> None:
        self.signals[signal.id] = signal

    def trigger_cycle(self) -> None:
        print("\n--- Cycle Tick ---")
        for s in self.signals.values():
            s.trigger_cycle()

    def handle_emergency(self, lane_id: str) -> None:
        if lane_id in self.signals:
            self.signals[lane_id].emergency_override()

if __name__ == "__main__":
    controller = IntersectionController()
    controller.add_signal(TrafficSignal("North-South", 30, 5, 25))
    controller.trigger_cycle()
    controller.trigger_cycle()
    controller.handle_emergency("North-South")

