/**
 * Low-Level Design: Dual Chess Clock
 * Design Patterns Applied:
 *  - Observer Pattern: Real-time tick alerts and flag-fall timeout notifications
 *  - State Pattern: Clock states (WhiteTurnState, BlackTurnState, PausedState)
 *  - Strategy Pattern: Increment algorithms (Fischer increment vs Bronstein delay)
 */

import java.util.*;

enum ClockMode { WHITE_TURN, BLACK_TURN, PAUSED, FLAGGED }

// --- [DESIGN PATTERN: Observer] Observer for UI and digital board listeners ---
interface ClockListener {
    void onTick(String activePlayer, long remainingMillis);
    void onFlagFall(String timedOutPlayer);
}

class ConsoleClockDisplay implements ClockListener {
    @Override
    public void onTick(String activePlayer, long remainingMillis) {
        System.out.println("⏱ [" + activePlayer + "] " + (remainingMillis / 1000) + "s remaining");
    }
    @Override
    public void onFlagFall(String timedOutPlayer) {
        System.out.println("🚩 TIME OUT! " + timedOutPlayer + " flagged out!");
    }
}

// --- [DESIGN PATTERN: Strategy] Time increment calculation strategy ---
interface IncrementStrategy {
    long calculateIncrement(long baseIncrementMillis, long elapsedMoveMillis);
}

class FischerIncrementStrategy implements IncrementStrategy {
    @Override
    public long calculateIncrement(long baseIncrementMillis, long elapsedMoveMillis) {
        // Fischer adds fixed bonus on each completed move
        return baseIncrementMillis;
    }
}

class BronsteinDelayStrategy implements IncrementStrategy {
    @Override
    public long calculateIncrement(long baseIncrementMillis, long elapsedMoveMillis) {
        // Bronstein adds back elapsed time up to base increment
        return Math.min(baseIncrementMillis, elapsedMoveMillis);
    }
}

// --- [DESIGN PATTERN: State] State interface managing active clock behavior ---
interface ClockState {
    void pressClock(ChessClock context);
    void pause(ChessClock context);
}

class WhiteTurnState implements ClockState {
    @Override
    public void pressClock(ChessClock context) {
        context.applyIncrementToWhite();
        context.setState(new BlackTurnState());
        System.out.println(">> Switch to Black's turn");
    }
    @Override
    public void pause(ChessClock context) {
        context.setState(new PausedState(this));
    }
}

class BlackTurnState implements ClockState {
    @Override
    public void pressClock(ChessClock context) {
        context.applyIncrementToBlack();
        context.setState(new WhiteTurnState());
        System.out.println(">> Switch to White's turn");
    }
    @Override
    public void pause(ChessClock context) {
        context.setState(new PausedState(this));
    }
}

class PausedState implements ClockState {
    private final ClockState previousState;
    public PausedState(ClockState previousState) { this.previousState = previousState; }
    @Override
    public void pressClock(ChessClock context) {
        System.out.println("Clock is paused. Resume before making move.");
    }
    @Override
    public void pause(ChessClock context) {
        context.setState(previousState);
        System.out.println(">> Resumed clock");
    }
}

class ChessClock {
    private ClockState currentState;
    private long whiteMillis;
    private long blackMillis;
    private final long incrementMillis;
    private final IncrementStrategy incrementStrategy;
    private final List<ClockListener> listeners = new ArrayList<>();

    public ChessClock(long initialMinutes, long incrementSeconds, IncrementStrategy strategy) {
        this.whiteMillis = initialMinutes * 60 * 1000;
        this.blackMillis = initialMinutes * 60 * 1000;
        this.incrementMillis = incrementSeconds * 1000;
        this.incrementStrategy = strategy;
        this.currentState = new WhiteTurnState();
    }

    public void addListener(ClockListener listener) { listeners.add(listener); }
    public void setState(ClockState state) { this.currentState = state; }

    public void pressButton() { currentState.pressClock(this); }
    public void togglePause() { currentState.pause(this); }

    public void applyIncrementToWhite() {
        whiteMillis += incrementStrategy.calculateIncrement(incrementMillis, 2000);
        notifyTick("White", whiteMillis);
    }
    public void applyIncrementToBlack() {
        blackMillis += incrementStrategy.calculateIncrement(incrementMillis, 2000);
        notifyTick("Black", blackMillis);
    }

    private void notifyTick(String player, long remaining) {
        for (ClockListener l : listeners) l.onTick(player, remaining);
    }
}

public class Main {
    public static void main(String[] args) {
        ChessClock clock = new ChessClock(5, 3, new FischerIncrementStrategy());
        clock.addListener(new ConsoleClockDisplay());

        System.out.println("--- Starting Blitz Match (5 min + 3s increment) ---");
        clock.pressButton(); // White moves -> switch to Black
        clock.pressButton(); // Black moves -> switch to White
        clock.togglePause();  // Pause game
        clock.togglePause();  // Resume game
    }
}

