    virtual ~LogHandler() = default;

    void setNext(std::shared_ptr<LogHandler> n) { next = n; }
    void addAppender(std::shared_ptr<Appender> a) { appenders.push_back(a); }

    void log(LogLevel lvl, const std::string& msg) {
        if (lvl == level) {
            for (auto& a : appenders) a->write(msg);
        } else if (next) {
            next->log(lvl, msg);
        }
