"""
Low-Level Design: Logger Framework
Design Patterns Applied:
 - Chain of Responsibility: Log levels delegate through handler chain
 - Singleton Pattern: Global thread-safe logger
 - Strategy Pattern: Pluggable destinations (Console, File)
"""

from enum import Enum
from abc import ABC, abstractmethod
from typing import Optional, List

class LogLevel(Enum):
    INFO = 1
    WARN = 2
    ERROR = 3

# --- [DESIGN PATTERN: Strategy] Appender destination strategy ---
class Appender(ABC):
    @abstractmethod
    def append(self, text: str) -> None:
        pass

class ConsoleAppender(Appender):
    def append(self, text: str) -> None:
        print(f"[CONSOLE] {text}")

# --- [DESIGN PATTERN: Chain of Responsibility] Handler hierarchy ---
class LogHandler(ABC):
    def __init__(self, level: LogLevel):
        self.level = level
        self.next_handler: Optional['LogHandler'] = None
        self.appenders: List[Appender] = []

    def set_next(self, next_handler: 'LogHandler') -> 'LogHandler':
        self.next_handler = next_handler
        return next_handler

    def add_appender(self, appender: Appender) -> None:
        self.appenders.append(appender)

    def log(self, level: LogLevel, message: str) -> None:
        if self.level == level:
            for app in self.appenders:
                app.append(f"[{level.name}] {message}")
        elif self.next_handler:
            self.next_handler.log(level, message)

class InfoHandler(LogHandler):
    def __init__(self): super().__init__(LogLevel.INFO)

class ErrorHandler(LogHandler):
    def __init__(self): super().__init__(LogLevel.ERROR)

# --- [DESIGN PATTERN: Singleton] Singleton logger ---
class Logger:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(Logger, cls).__new__(cls)
            info = InfoHandler()
            error = ErrorHandler()
            appender = ConsoleAppender()
            info.add_appender(appender)
            error.add_appender(appender)
            info.set_next(error)
            cls._instance.chain = info
        return cls._instance

    def info(self, msg: str) -> None:
        self.chain.log(LogLevel.INFO, msg)

    def error(self, msg: str) -> None:
        self.chain.log(LogLevel.ERROR, msg)

if __name__ == "__main__":
    logger = Logger()
    logger.info("Server booted in 120ms")
    logger.error("Connection pool exhausted")

