 * Design Patterns Applied:
 *  - Factory Method: Vehicle and parking space creation
 *  - Strategy: Dynamic parking tariff calculation
 *  - Singleton: Parking lot coordinator
 *  - Observer: Floor display vacancy monitoring
 */

#include <iostream>
#include <memory>
#include <string>
#include <unordered_map>

enum class VehicleType { MOTORCYCLE, CAR, TRUCK };

// --- [DESIGN PATTERN: Strategy] Tariff computation ---
class FeeStrategy {
public:
    virtual ~FeeStrategy() = default;
    virtual double calculate(VehicleType type, int hours) = 0;
};

class StandardFee : public FeeStrategy {
public:
    double calculate(VehicleType type, int hours) override {
        double rate = (type == VehicleType::CAR) ? 3.0 : 1.5;
        return hours * rate;
    }
};

// --- [DESIGN PATTERN: Singleton] Parking lot singleton ---
class ParkingLot {
    std::unordered_map<std::string, bool> spots;
    std::unique_ptr<FeeStrategy> feeStrat;
public:
    static ParkingLot& getInstance() {
        static ParkingLot instance;
        return instance;
    }
    ParkingLot() : feeStrat(std::make_unique<StandardFee>()) {
        spots["A1"] = false;
        spots["A2"] = false;
    }
    bool park(const std::string& spotId) {
        if (!spots[spotId]) {
            spots[spotId] = true;
            std::cout << "Parked at spot " << spotId << "\n";
            return true;
        }
        return false;
    }
    double exit(const std::string& spotId, VehicleType type, int hours) {
        spots[spotId] = false;
        return feeStrat->calculate(type, hours);
    }
};

int main() {
