    std::mt19937 gen{1337};
    std::uniform_int_distribution<> dis{1, 6};
public:
    int roll() override { return dis(gen); }
};

struct Player {
    std::string name;
    int pos = 0;
};

// --- [DESIGN PATTERN: Context / Game Manager] ---
class SnakeLadderGame {
    int boardSize;
    std::unordered_map<int, int> jumps;
    std::queue<Player> players;
    std::unique_ptr<DiceStrategy> dice;
public:
    SnakeLadderGame(int size, std::unique_ptr<DiceStrategy> d) : boardSize(size), dice(std::move(d)) {}
    void addJump(int from, int to) { jumps[from] = to; }
    void addPlayer(const Player& p) { players.push(p); }

    void playTurn() {
        if (players.empty()) return;
        Player p = players.front(); players.pop();
        int r = dice->roll();
        int next = p.pos + r;
        if (next <= boardSize) {
            if (jumps.count(next)) next = jumps[next];
            p.pos = next;
            std::cout << "🎲 [" << p.name << "] rolled " << r << " -> pos " << p.pos << "\n";
            if (p.pos == boardSize) {
                std::cout << "🏆 " << p.name << " WINS!\n";
                return;
            }
        }
        players.push(p);
    }
};

