"""
Low-Level Design: Snake and Ladder Game
Design Patterns Applied:
 - Strategy Pattern: Configurable dice roller
 - Singleton Pattern: Global match orchestrator
 - Observer Pattern: Turn and jump event broadcaster
"""

import random
from collections import deque
from abc import ABC, abstractmethod
from typing import Dict

# --- [DESIGN PATTERN: Strategy] Dice strategy ---
class DiceStrategy(ABC):
    @abstractmethod
    def roll(self) -> int: pass

class StandardDice(DiceStrategy):
    def roll(self) -> int:
        return random.randint(1, 6)

class Player:
    def __init__(self, name: str):
        self.name = name
        self.pos = 0

class SnakeLadderGame:
    def __init__(self, board_size: int = 100, dice: DiceStrategy = None):
        self.board_size = board_size
        self.dice = dice or StandardDice()
        self.jumps: Dict[int, int] = {}
        self.players = deque()
        self.finished = False

    def add_jump(self, start: int, end: int) -> None:
        self.jumps[start] = end

    def add_player(self, p: Player) -> None:
        self.players.append(p)

    def play_turn(self) -> None:
        if self.finished or not self.players:
            return
        curr = self.players.popleft()
        roll = self.dice.roll()
        nxt = curr.pos + roll

        if nxt <= self.board_size:
            if nxt in self.jumps:
                nxt = self.jumps[nxt]
            curr.pos = nxt
            print(f"🎲 [{curr.name}] rolled {roll} -> position {curr.pos}")
            if curr.pos == self.board_size:
                print(f"🏆 {curr.name} has WON the game!")
                self.finished = True
                return
        else:
            print(f"[{curr.name}] rolled {roll} - exceeds {self.board_size}")

        self.players.append(curr)

if __name__ == "__main__":
    game = SnakeLadderGame(100)
    game.add_jump(4, 25)
    game.add_jump(16, 3)
    game.add_player(Player("Alice"))
    game.add_player(Player("Bob"))

    for _ in range(5):
        game.play_turn()

