/**
 * Low-Level Design: In-Memory Cache System
 * Design Patterns Applied:
 *  - Strategy Pattern: LRU eviction algorithm
 *  - Proxy Pattern: Read-through cache caching behind data layer
 *  - Singleton Pattern: Cache instance manager
 */

#include <iostream>
#include <unordered_map>
#include <list>
#include <string>
#include <memory>

// --- [DESIGN PATTERN: Strategy] Eviction policy ---
class LRUCache {
    int cap;
    std::list<std::string> lruList;
    std::unordered_map<std::string, std::pair<std::string, std::list<std::string>::iterator>> map;
public:
    LRUCache(int c) : cap(c) {}

    std::string get(const std::string& key) {
        if (!map.count(key)) return "";
        lruList.erase(map[key].second);
        lruList.push_front(key);
        map[key].second = lruList.begin();
        return map[key].first;
    }

    void put(const std::string& key, const std::string& val) {
        if (map.count(key)) {
            lruList.erase(map[key].second);
        } else if ((int)map.size() >= cap) {
            std::string oldest = lruList.back();
            lruList.pop_back();
            map.erase(oldest);
            std::cout << "🗑️ Evicted: " << oldest << "\n";
        }
        lruList.push_front(key);
        map[key] = {val, lruList.begin()};
    }
};

int main() {
    LRUCache cache(2);
    cache.put("k1", "v1");
    cache.put("k2", "v2");
    std::cout << "k1: " << cache.get("k1") << "\n";
    cache.put("k3", "v3"); // Evicts k2
    std::cout << "k2 (evicted): " << (cache.get("k2").empty() ? "None" : cache.get("k2")) << "\n";
    return 0;
}

