};

class FileNode : public FSNode {
    std::string name, content;
public:
    FileNode(std::string n, std::string c) : name(std::move(n)), content(std::move(c)) {}
    std::string getName() const override { return name; }
    int getSize() const override { return content.size(); }
    void print(const std::string& indent) const override {
        std::cout << indent << "📄 " << name << " (" << getSize() << "B)\n";
    }
};

class DirNode : public FSNode {
    std::string name;
    std::vector<std::shared_ptr<FSNode>> children;
public:
    DirNode(std::string n) : name(std::move(n)) {}
    std::string getName() const override { return name; }
    void add(std::shared_ptr<FSNode> node) { children.push_back(node); }
    int getSize() const override {
        int tot = 0;
        for (const auto& c : children) tot += c->getSize();
        return tot;
    }
    void print(const std::string& indent) const override {
        std::cout << indent << "📁 " << name << "/\n";
        for (const auto& c : children) c->print(indent + "  ");
    }
};

int main() {
