"""
Low-Level Design: In-Memory File System
Design Patterns Applied:
 - Composite Pattern: Treats File and Directory uniformly
 - Command Pattern: Encapsulates actions (create, edit, delete)
 - Iterator Pattern: Directory tree traversal
"""

from abc import ABC, abstractmethod
from typing import List

# --- [DESIGN PATTERN: Composite] Base entry ---
class FSEntry(ABC):
    @abstractmethod
    def get_size(self) -> int: pass
    @abstractmethod
    def display(self, indent: str = "") -> None: pass

class File(FSEntry):
    def __init__(self, name: str, content: str = ""):
        self.name = name
        self.content = content
    def get_size(self) -> int: return len(self.content)
    def display(self, indent: str = "") -> None:
        print(f"{indent}📄 {self.name} ({self.get_size()}B)")

class Directory(FSEntry):
    def __init__(self, name: str):
        self.name = name
        self.children: List[FSEntry] = []
    def add(self, entry: FSEntry) -> None:
        self.children.append(entry)
    def get_size(self) -> int:
        return sum(c.get_size() for c in self.children)
    def display(self, indent: str = "") -> None:
        print(f"{indent}📁 {self.name}/")
        for c in self.children:
            c.display(indent + "  ")

if __name__ == "__main__":
    root = Directory("root")
    root.add(File("config.yaml", "host: localhost"))
    root.display()

