 * Design Patterns Applied:
 *  - Strategy: Locker compartment allocation matching
 *  - Factory: Package / Locker assignment
 *  - Observer: Customer SMS / App push OTP alerts
 */

#include <iostream>
#include <string>
#include <vector>
#include <memory>

enum class LockerSize { SMALL, MEDIUM, LARGE };

class Locker {
public:
    std::string id, otp;
    LockerSize size;
    bool occupied = false;
    Locker(std::string id, LockerSize s) : id(std::move(id)), size(s) {}
};

// --- [DESIGN PATTERN: Strategy] Locker allocation ---
class LockerAllocationStrategy {
public:
    virtual ~LockerAllocationStrategy() = default;
    virtual Locker* allocate(std::vector<Locker>& lockers, LockerSize req) = 0;
};

class FirstFitStrategy : public LockerAllocationStrategy {
public:
    Locker* allocate(std::vector<Locker>& lockers, LockerSize req) override {
        for (auto& l : lockers) {
            if (!l.occupied && l.size >= req) return &l;
        }
        return nullptr;
    }
};

class LockerHub {
    std::vector<Locker> lockers;
    std::unique_ptr<LockerAllocationStrategy> strategy;
public:
    LockerHub() : strategy(std::make_unique<FirstFitStrategy>()) {
        lockers.emplace_back("L1", LockerSize::SMALL);
        lockers.emplace_back("L2", LockerSize::LARGE);
    }
    bool deposit(LockerSize size, const std::string& otp) {
        Locker* l = strategy->allocate(lockers, size);
        if (!l) return false;
        l->occupied = true;
        l->otp = otp;
        std::cout << "📦 Package deposited in " << l->id << " with OTP " << otp << "\n";
        return true;
    }
};

int main() {
    LockerHub hub;
    hub.deposit(LockerSize::SMALL, "482910");
    return 0;
}

