 - Strategy Pattern: Locker compartment search strategy
 - Factory Pattern: Package and locker generation
 - Observer Pattern: Dispatches pickup PIN to customer
"""

from enum import Enum
from abc import ABC, abstractmethod
from typing import List, Optional

class LockerSize(Enum):
    SMALL = 1
    MEDIUM = 2
    LARGE = 3

class LockerCompartment:
    def __init__(self, slot_id: str, size: LockerSize):
        self.slot_id = slot_id
        self.size = size
        self.occupied = False
        self.otp: Optional[str] = None

