class AllocationStrategy(ABC):
    @abstractmethod
    def select(self, lockers: List[LockerCompartment], size: LockerSize) -> Optional[LockerCompartment]: pass

class BestFitStrategy(AllocationStrategy):
    def select(self, lockers: List[LockerCompartment], size: LockerSize) -> Optional[LockerCompartment]:
        for l in lockers:
            if not l.occupied and l.size.value >= size.value:
                return l
        return None

