        self.strategy = BestFitStrategy()

    def deposit(self, size: LockerSize, otp: str) -> bool:
        slot = self.strategy.select(self.lockers, size)
        if slot:
            slot.occupied = True
            slot.otp = otp
            print(f"📦 Stored in {slot.slot_id} [PIN: {otp}]")
            return True
        print("❌ No locker available")
        return False

