    double getPrice(SeatType type, boolean isWeekend);
}

class StandardPricingStrategy implements SeatPricingStrategy {
    @Override
    public double getPrice(SeatType type, boolean isWeekend) {
        double base = switch (type) {
            case SILVER -> 10.0;
            case GOLD -> 15.0;
            case PLATINUM -> 25.0;
        };
        return isWeekend ? base * 1.25 : base;
    }
}

// --- [DESIGN PATTERN: Observer] Seat release notifier ---
