        this.seatNumber = seatNumber;
        this.type = type;
    }
    public String getSeatNumber() { return seatNumber; }
    public SeatType getType() { return type; }
    public SeatStatus getStatus() { return status; }
    public void setStatus(SeatStatus status) { this.status = status; }
}

class ShowBookingService {
    private final Map<String, Seat> seats = new HashMap<>();
    private final SeatPricingStrategy pricingStrategy;
    private final List<SeatHoldObserver> observers = new ArrayList<>();

    public ShowBookingService(SeatPricingStrategy strategy) {
        this.pricingStrategy = strategy;
    }

    public void addSeat(Seat seat) { seats.put(seat.getSeatNumber(), seat); }
    public void addObserver(SeatHoldObserver o) { observers.add(o); }

    public synchronized boolean holdSeats(List<String> seatNumbers, String userId) {
        for (String sn : seatNumbers) {
            Seat s = seats.get(sn);
            if (s == null || s.getStatus() != SeatStatus.AVAILABLE) {
                System.out.println("❌ Seat " + sn + " is already reserved or booked!");
                return false;
            }
        }
        for (String sn : seatNumbers) {
            seats.get(sn).setStatus(SeatStatus.HELD);
        }
        System.out.println("⏳ Held seats " + seatNumbers + " for user " + userId + " (10m TTL lock)");
        return true;
    }

    public synchronized boolean confirmBooking(List<String> seatNumbers) {
        double total = 0.0;
        for (String sn : seatNumbers) {
            Seat s = seats.get(sn);
            if (s.getStatus() != SeatStatus.HELD) return false;
            s.setStatus(SeatStatus.BOOKED);
            total += pricingStrategy.getPrice(s.getType(), false);
        }
        System.out.printf("🎟️ Booking CONFIRMED for seats %s! Total: $%.2f%n", seatNumbers, total);
        return true;
    }
}

public class Main {
