    public void handleRequest(ElevatorCar car, int floor) {
        if (floor > car.getCurrentFloor()) {
            car.setDirection(Direction.UP);
            car.setState(new MovingUpState());
            System.out.println("🔼 Elevator [" + car.getId() + "] starting UP to floor " + floor);
        } else if (floor < car.getCurrentFloor()) {
            car.setDirection(Direction.DOWN);
            car.setState(new MovingDownState());
            System.out.println("🔽 Elevator [" + car.getId() + "] starting DOWN to floor " + floor);
        }
    }
}

class MovingUpState implements ElevatorState {
    @Override
    public void handleRequest(ElevatorCar car, int floor) {
        car.addStop(floor);
    }
}

class MovingDownState implements ElevatorState {
    @Override
    public void handleRequest(ElevatorCar car, int floor) {
        car.addStop(floor);
    }
}

class ElevatorCar {
    private final int id;
    private int currentFloor = 1;
    private Direction direction = Direction.IDLE;
    private ElevatorState state = new IdleState();
    private final TreeSet<Integer> stops = new TreeSet<>();

    public ElevatorCar(int id) { this.id = id; }
    public int getId() { return id; }
    public int getCurrentFloor() { return currentFloor; }
    public Direction getDirection() { return direction; }
    public void setDirection(Direction d) { this.direction = d; }
    public void setState(ElevatorState s) { this.state = s; }
    public void addStop(int f) { stops.add(f); }

    public void requestFloor(int floor) {
        stops.add(floor);
        state.handleRequest(this, floor);
    }
}

// --- [DESIGN PATTERN: Strategy] Elevator selection algorithm ---
interface DispatchStrategy {
    ElevatorCar pickBestCar(List<ElevatorCar> cars, int sourceFloor, Direction dir);
}

class NearestCarStrategy implements DispatchStrategy {
    @Override
    public ElevatorCar pickBestCar(List<ElevatorCar> cars, int floor, Direction dir) {
        ElevatorCar best = null;
        int minDistance = Integer.MAX_VALUE;
        for (ElevatorCar c : cars) {
            int dist = Math.abs(c.getCurrentFloor() - floor);
            if (dist < minDistance) {
                minDistance = dist;
                best = c;
            }
        }
        return best;
    }
}

public class Main {
    public static void main(String[] args) {
        List<ElevatorCar> bank = List.of(new ElevatorCar(1), new ElevatorCar(2));
        DispatchStrategy dispatcher = new NearestCarStrategy();

        System.out.println("--- Elevator Dispatch Simulation ---");
