public:
    int id;
    int currentFloor = 1;
    Direction dir = Direction.IDLE;
    Elevator(int id) : id(id) {}
    void goTo(int floor) {
        dir = (floor > currentFloor) ? Direction.UP : Direction.DOWN;
        std::cout << "🛗 Car #" << id << " moving from " << currentFloor << " to " << floor << "\n";
        currentFloor = floor;
        dir = Direction.IDLE;
    }
};

