class DispatchStrategy {
public:
    virtual ~DispatchStrategy() = default;
    virtual Elevator* selectCar(std::vector<Elevator>& cars, int targetFloor) = 0;
};

class NearestDispatch : public DispatchStrategy {
public:
    Elevator* selectCar(std::vector<Elevator>& cars, int targetFloor) override {
        Elevator* best = nullptr;
        int minD = 1e9;
        for (auto& c : cars) {
            int d = std::abs(c.currentFloor - targetFloor);
            if (d < minD) { minD = d; best = &c; }
        }
        return best;
    }
};

