import java.util.*;

enum Color { WHITE, BLACK }

abstract class Piece {
    protected final Color color;
    public Piece(Color color) { this.color = color; }
    public Color getColor() { return color; }
    public abstract boolean canMove(int fromR, int fromC, int toR, int toC);
}

class Knight extends Piece {
    public Knight(Color color) { super(color); }
    @Override
    public boolean canMove(int fromR, int fromC, int toR, int toC) {
        int dr = Math.abs(fromR - toR);
        int dc = Math.abs(fromC - toC);
        return (dr == 1 && dc == 2) || (dr == 2 && dc == 1);
    }
}

// --- [DESIGN PATTERN: Factory Method] Piece factory ---
class PieceFactory {
    public static Piece createKnight(Color color) { return new Knight(color); }
}

// --- [DESIGN PATTERN: Command] Move command ---
interface MoveCommand {
    boolean execute();
    void undo();
}

class ChessMove implements MoveCommand {
    private final Piece piece;
    private final int fromR, fromC, toR, toC;

    public ChessMove(Piece piece, int fromR, int fromC, int toR, int toC) {
        this.piece = piece;
        this.fromR = fromR; this.fromC = fromC; this.toR = toR; this.toC = toC;
    }

    @Override
    public boolean execute() {
        if (!piece.canMove(fromR, fromC, toR, toC)) {
            System.out.println("❌ Illegal move for " + piece.getClass().getSimpleName());
            return false;
        }
        System.out.printf("♟️ Move executed: (%d,%d) -> (%d,%d)%n", fromR, fromC, toR, toC);
        return true;
    }

    @Override
    public void undo() {
        System.out.printf("↩️ Move undone: back to (%d,%d)%n", fromR, fromC);
    }
}

public class Main {
    public static void main(String[] args) {
        Piece whiteKnight = PieceFactory.createKnight(Color.WHITE);
        ChessMove move1 = new ChessMove(whiteKnight, 0, 1, 2, 2); // Valid L-shape
        move1.execute();

        ChessMove move2 = new ChessMove(whiteKnight, 2, 2, 2, 4); // Invalid
        move2.execute();
    }
}

