// --- [DESIGN PATTERN: Observer] Real-time collaborator sync ---
interface DocumentObserver {
    void onDocumentModified(int version, String fullText);
}

class CollaboratorView implements DocumentObserver {
    private final String userId;
    public CollaboratorView(String userId) { this.userId = userId; }
    @Override
    public void onDocumentModified(int version, String fullText) {
        System.out.printf("💻 [Collaborator %s] Sync v%d: \"%s\"%n", userId, version, fullText);
    }
}

// --- [DESIGN PATTERN: Command] Text editing command with undo ---
interface EditorCommand {
    void execute();
    void undo();
}

class InsertTextCommand implements EditorCommand {
    private final StringBuilder doc;
    private final int index;
    private final String text;

    public InsertTextCommand(StringBuilder doc, int index, String text) {
        this.doc = doc; this.index = index; this.text = text;
    }

    @Override
    public void execute() {
        doc.insert(index, text);
    }

    @Override
    public void undo() {
        doc.delete(index, index + text.length());
    }
}

class CollaborativeDocument {
    private final StringBuilder content = new StringBuilder();
    private int version = 0;
    private final Stack<EditorCommand> history = new Stack<>();
    private final List<DocumentObserver> observers = new ArrayList<>();

    public void addObserver(DocumentObserver o) { observers.add(o); }

    public synchronized void applyCommand(EditorCommand cmd) {
        cmd.execute();
        history.push(cmd);
        version++;
        for (DocumentObserver o : observers) o.onDocumentModified(version, content.toString());
    }

    public synchronized void undo() {
        if (!history.isEmpty()) {
            EditorCommand cmd = history.pop();
            cmd.undo();
            version++;
            for (DocumentObserver o : observers) o.onDocumentModified(version, content.toString());
        }
    }

    public StringBuilder getContent() { return content; }
}

public class Main {
    public static void main(String[] args) {
        CollaborativeDocument doc = new CollaborativeDocument();
        doc.addObserver(new CollaboratorView("Alice"));
        doc.addObserver(new CollaboratorView("Bob"));

        System.out.println("--- Collaborative Editing ---");
        doc.applyCommand(new InsertTextCommand(doc.getContent(), 0, "Hello "));
        doc.applyCommand(new InsertTextCommand(doc.getContent(), 6, "World!"));
        doc.undo();
    }
}

