    AppendTextCommand(std::string t) : text(std::move(t)) {}
    void execute(std::string& doc) override { doc += text; }
    void undo(std::string& doc) override {
        if (doc.size() >= text.size()) doc.resize(doc.size() - text.size());
    }
};

class Editor {
    std::string buffer;
    std::stack<std::unique_ptr<EditCommand>> history;
public:
    void apply(std::unique_ptr<EditCommand> cmd) {
        cmd->execute(buffer);
        history.push(std::move(cmd));
        std::cout << "📄 Doc: \"" << buffer << "\"\n";
    }
    void undo() {
        if (!history.empty()) {
            history.top()->undo(buffer);
            history.pop();
            std::cout << "↩️ Undone! Doc: \"" << buffer << "\"\n";
        }
    }
};

int main() {
    Editor editor;
    editor.apply(std::make_unique<AppendTextCommand>("Design "));
    editor.apply(std::make_unique<AppendTextCommand>("Patterns"));
    editor.undo();
    return 0;
