 - Command Pattern: Encapsulates typing / deletion with Undo capability
 - Observer Pattern: Real-time collaborator notification
 - Strategy Pattern: Operational Transformation logic
"""

from abc import ABC, abstractmethod

# --- [DESIGN PATTERN: Command] Text action ---
class Command(ABC):
    @abstractmethod
    def execute(self, text: list) -> None: pass
    @abstractmethod
    def undo(self, text: list) -> None: pass

class AppendCommand(Command):
    def __init__(self, string: str): self.string = string
    def execute(self, text: list) -> None:
        text.append(self.string)
    def undo(self, text: list) -> None:
        if text: text.pop()

class DocEditor:
    def __init__(self):
        self.text = []
        self.undo_stack = []

    def type_text(self, string: str) -> None:
        cmd = AppendCommand(string)
        cmd.execute(self.text)
        self.undo_stack.append(cmd)
        print("📄 Document: " + "".join(self.text))

    def undo(self) -> None:
        if self.undo_stack:
            cmd = self.undo_stack.pop()
            cmd.undo(self.text)
            print("↩️ Undone -> " + "".join(self.text))

if __name__ == "__main__":
    doc = DocEditor()
    doc.type_text("Hello ")
    doc.type_text("World")
    doc.undo()

