    public double calculateFare(double distanceKm, int seats) {
        return (4.0 + distanceKm * 1.5) / Math.max(1, seats);
    }
}

// --- [DESIGN PATTERN: Observer] Telemetry tracking observer ---
interface DriverTelemetryObserver {
    void onLocationUpdated(String driverId, double lat, double lng);
}

class RiderTrackingDisplay implements DriverTelemetryObserver {
    @Override
    public void onLocationUpdated(String driverId, double lat, double lng) {
        System.out.printf("📍 [Live Map] Driver %s location: (%.4f, %.4f)%n", driverId, lat, lng);
    }
}

class RideSharingCoordinator {
    private final FareStrategy fareStrategy = new StandardCarpoolFareStrategy();
    private final List<DriverTelemetryObserver> observers = new ArrayList<>();

    public void addObserver(DriverTelemetryObserver o) { observers.add(o); }

    public double quoteTrip(double distanceKm, int seats) {
        return fareStrategy.calculateFare(distanceKm, seats);
    }

    public void updateDriverGps(String driverId, double lat, double lng) {
        for (DriverTelemetryObserver o : observers) o.onLocationUpdated(driverId, lat, lng);
    }
}

public class Main {
    public static void main(String[] args) {
        RideSharingCoordinator service = new RideSharingCoordinator();
        service.addObserver(new RiderTrackingDisplay());

        double fare = service.quoteTrip(15.0, 3);
        System.out.printf("Split Carpool Fare per person: $%.2f%n", fare);

        service.updateDriverGps("DRV-99", 37.7749, -122.4194);
    }
}

