/**
 * Low-Level Design: Ride Sharing Peer Service
 * Design Patterns Applied:
 *  - Strategy: Fare calculation algorithm
 *  - Observer: Telemetry GPS position observer
 *  - State: Carpool lifecycle management
 */

#include <iostream>
#include <string>
#include <vector>
#include <memory>

// --- [DESIGN PATTERN: Observer] Telemetry observer ---
class TelemetryObserver {
public:
    virtual ~TelemetryObserver() = default;
    virtual void onGps(double lat, double lng) = 0;
};

class MapView : public TelemetryObserver {
public:
    void onGps(double lat, double lng) override {
        std::cout << "📍 Driver live GPS: " << lat << ", " << lng << "\n";
    }
};

class RideShare {
    std::vector<std::shared_ptr<TelemetryObserver>> observers;
public:
    void addObserver(std::shared_ptr<TelemetryObserver> o) { observers.push_back(o); }
    void broadcastLocation(double lat, double lng) {
        for (auto& o : observers) o->onGps(lat, lng);
    }
};

int main() {
    RideShare app;
    app.addObserver(std::make_shared<MapView>());
    app.broadcastLocation(40.7128, -74.0060);
    return 0;
}

