"""
Low-Level Design: Ride Sharing Peer Service
Design Patterns Applied:
 - Strategy Pattern: Dynamic fare calculation
 - Observer Pattern: Real-time driver GPS telemetry
 - State Pattern: Trip state transitions
"""

from abc import ABC, abstractmethod
from typing import List

# --- [DESIGN PATTERN: Observer] Telemetry listener ---
class TelemetryListener(ABC):
    @abstractmethod
    def on_location(self, lat: float, lng: float) -> None: pass

class LiveMapScreen(TelemetryListener):
    def on_location(self, lat: float, lng: float) -> None:
        print(f"📍 [Live Map] Driver at ({lat:.4f}, {lng:.4f})")

class RideShareSystem:
    def __init__(self):
        self.observers: List[TelemetryListener] = []

    def subscribe(self, o: TelemetryListener) -> None:
        self.observers.append(o)

    def update_position(self, lat: float, lng: float) -> None:
        for o in self.observers:
            o.on_location(lat, lng)

if __name__ == "__main__":
    system = RideShareSystem()
    system.subscribe(LiveMapScreen())
    system.update_position(37.7749, -122.4194)
